WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (540::BIGINT, 'El mae es un poco despistado pero ayuda bastante, si le pregunta algo más de una vez probablemente le haga algún comentario pero de igual manera le va a ayudar, quizes digitales y cierta flexibilidad con los trabajos. No hay clase aburrida, si pudiera matricular con el de nuevo, lo ha sin duda.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-20T00:00:00+00:00'::TIMESTAMPTZ, '58251a36acb83dc426f3f11a6b0fba3afebc2e79bac09e02867c1fdcc5a498bd'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (540::BIGINT, 'El mae es buena gente, pero de profe no la rifa, usted le toca ir de autodidacta y si se la pelo en la matricula y le toco con el metase a otra clase de quimica 2 con un compa, lo bueno es que avisa cuando hay quiz y son virtuales la mayoría, pero no se lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2026-07-16T00:00:00+00:00'::TIMESTAMPTZ, '06aef431c1587a58fd268689946e8a1e5d437cd5efe9268d54ac8beee4ee9c5a'::TEXT, ARRAY[614]::BIGINT[]),
    (540::BIGINT, 'El profe es tan pero tan chill que a veces juega en contra porque se le va el alma en paciencia, es muy desordenado y preguntarle algo es como hablarle a la pared porque no le da importancia. Es como un osito cariñosito pero va a tener que estudiar de forma independiente si quiere aprender algo.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'c498692ad3a0aee40476c19eccf42219a7d75cdf402099e0d931dd85051bc8e3'::TEXT, ARRAY[2738]::BIGINT[]),
    (540::BIGINT, 'Prepárese a descubrir la química usted solo, mi recomendación es hacerce amigo del profe, lo cual no es difícil ya que es una teja de persona, para la parte de calculos es bastante bueno, pero la teoría con el es muy confusa ya que sus ejemplos son imaginativos af. Pregunte todo lo pueda'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2025-07-23T00:00:00+00:00'::TIMESTAMPTZ, '3e29958e78beb5a822c25eb12db860a43ea0e60cb847bcd2aacc08117747444e'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'Ser autodidacta no es un privilegio sino una obligación con el profe, es imposible que le caiga mal pero como profesor es un tanto desordenado y en todo el semestre no hubo una sola practica, el le ayuda a pasar si de verdad cree que usted se lo merece'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'a397eec1410de6c5898f79c41c7be6cae98eaa9c9b830ffc5befb84171fe82dd'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (540::BIGINT, 'Se pasa fácil, sin embargo los conceptos son explicados de una manera laxa. Si quiere aprobar, es buena opción.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'f41ff3882530cff8d5f9977345ad4c885bc40229fbeca8fd5f9f2ea32990036b'::TEXT, ARRAY[3181, 3179]::BIGINT[]),
    (540::BIGINT, 'El mejor profe si quiere pasar las clases chill, solo que los quizzes tienden a ser de pocos puntos y los exámenes califica medio duro. Por la naturaleza de la clase no le prepara a uno tan bien por lo que puede ser que el curso le dé medio bajo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, '0747a9bfb6be4fc9313b80d104416ce577f41b891241cd00e62fe82e35421978'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Sí tiende a calificar duro los exámenes e informes, pero es muy tranquilo con la libreta (nunca la revisa solo si uno se la da) y los quices son en gaap. Te ayuda mil y un veces a que hagas las cosas bien y las entendas. Si le caes bien es probable que te ayude con unos puntillos a final de semestre'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'd3e28b6464025f41cc432799c4b1cfdd58560905f8f547bb2f6292d0051e62af'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'No lo recomiendo es demasiado desordenado, y califica demasiado duro, lo bueno es que los quiz son virtuales y la libreta casi no la revisa'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-11-10T00:00:00+00:00'::TIMESTAMPTZ, '0825192481237499447bd56e4481e79f7de085b82f0f1f0c0d9aa69b44afb6f0'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Química 1 no es un curso fácil pero creo es buena opción. El profe es muy buena gente, hace mucho quiz y escoge los mejores. Eso si, puede divagar bastante y a veces no se le entienden los ejemplos. Hay que ser muy autónomo y estudiar por cuenta propia, buscar videos para entender la teoría, etc.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2024-09-24T00:00:00+00:00'::TIMESTAMPTZ, '9703e279cfd1acc125a6679ae40cd1c08e4ae10459d359d673e24e300dfe2acd'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'Explica súper bien y no califica tan duro los informes, si ve que uno le pone a la clase le puede ayudar al final de semestre con unos puntillos y hace la clase entretenida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '984d171f5c6dcac24b2778f75dfd474d867af7e2f7a1754a5d5919eea058344d'::TEXT, ARRAY[567]::BIGINT[]),
    (540::BIGINT, 'Para primer ingreso en lab, este profe es excelente. Es comprensible con los estudinates, si usted muestra interés, él le va ayudar. Prepara muy bien para el examen de cátedra. Los quices a veces son un poco complicados. Pero lo más importante es que usted haga bien los informes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, '38b2e2a30a988274c57c3fe1744bba75e0da11a2147aff588ff4b1f2948b3ca8'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (540::BIGINT, 'Un profe muy buena nota, es amable con todos y siempre esta dispuesto a ayudar en las prácticas de laboratorio, cada clase hace un quiz pero siempre son cortos y sencillos, su forma de explicar es muy directa y hace que el estudiante se sienta a gusto.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c951f0fd9139022eae7caebae643fc1e20b93f8ad4a175671e56ebb8c22b815a'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (540::BIGINT, 'Como profesor es muy bueno y comprensivo, hace un quiz a la semana y al final de semestre elige los 8 mejores. Al explicar se desvía un poco pero si le pone bastante atención si entiende bien. Como persona es excelente y demasiado cómico. Lo único malo es la letra.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'b968bbb970f384c05388d687e4405785ae18a0261ff5c3b96903c5f9f2c2492a'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (540::BIGINT, 'Crea un ambiente cómodo con el estudiante, pero más que todo porque habla de su vida toda la clase, explica muy poco dela materia y además lo hace muy mal, se enreda solo y no sabe como responder preguntas de estudinates. Lo único bueno es que hace muchísimos quices y solo escoge los 8 mejores.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '11179b0b54fef2e01adecb8980b8f2510c22d8f165d250793017cf85c30c4c91'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'Para lab es un profe demasiado buena gente, muy amigable y un señor muy tierno, lo recomiendo muchísimo. Siempre ayuda con toda disposición en lo que uno necesite. SUPER RECOMENDADO.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-06T00:00:00+00:00'::TIMESTAMPTZ, '65619971b8a29000429bf6a218c7d0eb3167f955e67074f45a2ead74b99a0ff5'::TEXT, ARRAY[567, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Él lo ayuda a uno a motivarse mucho. Excelente persona. Como profesor cuesta entenderle pero con los materiales de la cátedra uno se pone al día, sin eso quizá usted esté siempre perdido'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-02-02T00:00:00+00:00'::TIMESTAMPTZ, '103a013ad3ef43cf1e01944234421d59898739d51ea8d4752b7d8e2a6ac990ae'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'El ambiente de la clase es muy bonito, pero durante la explicación se desconcentra y habla de anécdotas o datos curiosos de química gastando todo el tiempo y dejando incompleta la materia.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'e9065caa52d603910cb41777d7e5e4f8c061d04b43bc0cce3ca60bda5231db1d'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'No explica bien la teoría, no se le entiende'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos exámenes']::TEXT[], '2023-05-08T00:00:00+00:00'::TIMESTAMPTZ, '17b20d059bfa0b8371ff7dd5beabfda47f0165fdf0c420cbe5e9a1fcf594471f'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'Es demasiado paciente, capaz que te hace el informe pero animese a preguntarle de verdad, es demasiada buena persona.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'a96170ec2527351c14ff97fa55256ec2e7b091b07dee82fb2c3fbea2b8cc50d7'::TEXT, ARRAY[567, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Como profe de laboratorio es muy bueno, aligera mucho la clase y no hay presión, si le pides ayuda con los informes a rellenarlos él con gusto te ayuda, y es muy buena persona. Para laboratorio es de lo mejor que me ha pasado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2022-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'c56e95fa84ecb867dc0eba6735d5dec37eabd921e61497849f7fa2ff41a0c391'::TEXT, ARRAY[567, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Muy desordenado, sus clases son largas y confusas, no es bueno explicando, se desvía completamente del tema. Los quices no los elabora él y si algo está mal nunca responde. Su asistente también es muy desordenada. Hacen el curso imposible, no siguen la normativa de evaluaciones. GRAN NO'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'b7197f0988ac9c734a22a5658dafe2de03edaccf297eb6d105d7dde7a7cdfbc0'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'Es un amor de persona. Es muy comprensivo. Quizás no explica muy bien pero para un curso practico como laboratorio no es tan importante'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '045099a1e48f6cde014107ccd774c4febbac55f3b5acebe9dbfb9eab95ea263a'::TEXT, ARRAY[3181, 3179]::BIGINT[]),
    (540::BIGINT, 'No matricule, este profe no es bueno, no responde dudas, los quices no los hace él, si hay un error en el quiz y uno intenta reclamar le vale 3 hectareas, malo explicando y se desvía del tema demasiado MAL PROFESOR,sus clases solo servían para saber cuál tema se veía y buscarlo en internet'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'c73af5f61c68f66342853d2cbc2151a478f5a60fdbec173381bc84ce236105e0'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (540::BIGINT, 'NO MATRICULE CON ESTE PROFESOR. NO brinda ayuda, no explica, no da clases, el horario de clases lo usa como hora de consulta, no se preocupa por el estudiante. NO MATRICULE'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2021-08-27T00:00:00+00:00'::TIMESTAMPTZ, 'a9e1bf16af8d4d3e72654e78b5f8d2ca9cac9f4a5d62cb6d77484cc0d7b5d853'::TEXT, ARRAY[2738]::BIGINT[]),
    (540::BIGINT, 'El profesor es una excelente personal, pero no es muy buen profe. Da chance para entregar trabajos y es muy compresivo, pero es muy desordenado y no actualiza el TecDigital con las calificaciones hasta final del semestre.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '302f0554d29fb8dd36eb71fc7130f29f8817c91d27d2647efc84700f38880fdf'::TEXT, ARRAY[3181, 3179]::BIGINT[]),
    (540::BIGINT, 'Es excelente como persona, explica bien, brinda apoyo si alguien no pudo realizar alguna actividad da más tiempo, pero es muy desordenado respecto a los informes que se le entregan, todo lo revisa hasta el final, a veces las clases son largas y cuesta un poco que responda los mensajes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo']::TEXT[], '2021-06-17T00:00:00+00:00'::TIMESTAMPTZ, '78858f38e732f1b9694118157866022579041aa728aa9176bbfa21525aa0dd4d'::TEXT, ARRAY[3181, 3179]::BIGINT[]),
    (540::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-05-13T00:00:00+00:00'::TIMESTAMPTZ, 'ddcacf722f257913b5ce24253955ccae8b31c0f75a17cdc23eae2d246c9186d7'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (540::BIGINT, 'Muy desordenado y no se le entiende mucho, aveces subia la presentacion de cada tema muy tarde, las clases virtuales se desviaba mucho del tema y quedaban muchas dudas Tenia buena percepcion por los comentarios de el pero resulto otra cosa, tampoco responde los correos'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'a4e4c3876f682e5ec732f04faa1c7e97a50edde812de6b9e30ab5e49fddd578a'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'Se desvía mucho del tema. Es un desorden tanto él como la asistente que se tiene. No contesta dudas puntuales. Las notas duran toda la vida por darlas. En auto evaluaciones daba chance de volver a hacerlas para tratar de salir bien en el curso (lo único bueno).'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, '5403599cb65c80a8bf8a95629d06f29a52237b2ddcf13b11231e4c1278953716'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'Excelente persona, como profesor deja que desear debido a que es un poco desordenado y suele desviarse de la clase . Deja evaluaciones cortas tanto para hacer en clase como para hacer en la casa. Ayuda con los tiempos de entrega dando tiempo extra si se requiere. Es muy comprensivo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '22d51f71c7eb951267fedc5de630c813026d943667ba389dd2da6f83bba22e3d'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'El profe es una excelente persona y muy accesible, genera confianza en caso de tener dudas. No actualiza el TecDigital entonces usted no sabe como va hasta el final. Es comprensivo con los tiempos de entrega y en clases aveces se desvía un poco del tema. Se pasa fácil.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'ef60db6ad1248556c0cef1c93be7d0cec061e9df92160271d3eb14eb68741948'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'El profe no contesta las dudas puntuales y se pierde un poco por medios virtuales... pero al final se entiende e incluso ayuda a que todos pasen bien'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases largas']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '90cc20a67cecd79ea2887adf7c4f8bedf36092c33f04619c92c13684a80e7905'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'Excelente persona, super amable, pero la experiencia virtual no fue la mejor, entenderle fue complicado y los informes muchas veces eran demasiado confusos. Atendía dudas pero costaba mucho que respondiera, es comprensivo si se necesita más tiempo para entregar un trabajo.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '9125c6528865e4755329785cab937e821761ec9b78bbf14d9badbb5bee668ab1'::TEXT, ARRAY[3181, 3179]::BIGINT[]),
    (540::BIGINT, 'Mal profesor. Desordenado, no explica bien. Los informes que envía para hacer no son claros y cuando uno le pregunta nunca contesta. Deja los informes con menos de una semana para hacerlos. Buena persona, pero no lo recomiendo como profe!'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '119a4ab48601edcb690f7a4ae7144966ac327bbedeb73c84072d36b2606ede26'::TEXT, ARRAY[3181, 3179]::BIGINT[]),
    (540::BIGINT, 'Excelente persona, terrible profesor. Ayudo mucho al estudiante para pasar el curso, si uno tenía una duda con mucho gusto le ayudaba, pero en si un poco desordenado para dar la clase, yo solo encendía mi computadora y grababa la clase. Los quices son fáciles, uno que otro bien complicado.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '31885eb46265469923cd93dd3ba88a2b564bd0cb1cd4600a7e39b85066326315'::TEXT, ARRAY[1433]::BIGINT[]),
    (540::BIGINT, 'Es un buen profesor, se desvía mucho de los temas de clase pero conoce de la materia, trata de dar muchos ejemplos de la materia aplicados en la vida real y en ocasiones ayudan y en otros te enreda más. Estudiar por aparte ayuda a pasar.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'baaaec605a42a2e0abed73f19bf243c574084ba1d7ab0a009f7f7d47c30e3dac'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'En general como profesor regular, ya que es bastante desordenado con la clase y evaluaciones, muchos quizes y no se sabe hasta el final la nota. Es una gran persona, comprensible y muy permisible por lo que ayuda al final si hacen falta unos puntos'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Clases largas']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'c1ecd1e2b8a7d8bead05f9b0d5493e0b1fe38a58845e07894353f0bba39f4b41'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'El profe es súper linda persona pero explica muy raro, no tiene un orden para llevar el hilo de la materia. Si llevas con él debes de estudiar por tu cuenta. Hace muchos quizes por semana pero son muy cortos y sencillos. Lo malo es que es muy desordenado con el tec digital y no sabes como vas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Brinda apoyo']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'b5b9bc457b66c130f8a5f075e906c0b3a83b2404cf622699c3ef43814777008a'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'Es un amor de persona, pero como profesor no es muy claro y termina confundiendo a los estudiantes. Es muy importante estudiar y practicar por cuenta propia, porque en clases casi no se entiende nada.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador']::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, 'a67954938e80160f242b4e8dc3294a1b0529aaad9e80eb94994e4808b4e4c5ec'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'El profe en otros cursos de química es medio regular, pero en este es muy desordenado, no explica bien y es un poco irresponsable. Igual el mae siempre es buena nota con uno, pero no creo que uno aprenda nada'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo']::TEXT[], '2020-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'c2a926fff3933d177129529d834c42d475b6c93522cec9b52f8250757fc307c7'::TEXT, ARRAY[2738]::BIGINT[]),
    (540::BIGINT, 'No sabe explicar bien, todo lo deja a medias.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-05-05T00:00:00+00:00'::TIMESTAMPTZ, '4e4f6984bdfe6b65c246ea4314b5204a7c63d8d76dca2a8065672511894177d3'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (540::BIGINT, 'Puedo rajar que es el profe más malo que hay, No se le entiende nada. La parte de quices lo salva, la mayoría los hace grupales y eso es una ventaja.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'd32268997fe18bf25ee8224a696632514f566cd123b76a8a2faa92abd21eb2f6'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'El profe es muy buena persona pero la verdad no explica muy bien. Si usted tiene alguna duda el profe se lo aclara súper bien. Solamente dediquele tiempo para estudiar.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa']::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, '60627e8f5465a730ebc9a81c88beb68154da33a8052999a1ce052a07c188dc10'::TEXT, ARRAY[1434]::BIGINT[]),
    (540::BIGINT, 'Muy buen profe, solamente es de dedicarle tiempo al curso y de verdad querer aprender.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, '0f97dee03c9e8ef1f6b279fbed3da752698d5efa9dff9b5b2e8d9b2e83d4ce18'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (540::BIGINT, 'El en si como persona es muy amable y cómico; pero como profesor cuesta entenderle y explica la mitad de las cosas necesarias para el examen. Normalmente hace que los estudiantes pasen, pero si usted quiere aprender realmente será mejor que estudie de la comunidad.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '2be961a49fac97de81ebcf08768a47b9df4c5de450266d860ac008d5ca590f7d'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'Mae pichudo Sandoval buena nota'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2019-09-12T00:00:00+00:00'::TIMESTAMPTZ, '21e5bfbf8c081d98742e523af65c435ac98d7a52a4b0b2a6d640f2ee103168bd'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'El profesor cae muy bien, sin embargo cuesta entenderle. Hace muchos quices y califica muy duro. Matriculé con él si tiene un amplio conocimiento previo de la materia.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '7520b93572ec267ca77f3382f9c0431f6dd72ac20b7acafea3676ad261cfb135'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'Es pésimo profesor, no explica nada, se siente orgulloso de que no le pasen el curso. Para ganárselo hay que ser darle toda la atención que quiere. Los exámenes son sumamente difíciles y es hay que responder exactamente lo que él quiere. De un grupo de 55 pasaron 15.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e950d55958a15e1df9f9486f324de651e48c5f4026979c45b1f2287717bc014c'::TEXT, ARRAY[1434]::BIGINT[]),
    (540::BIGINT, 'Muy buen profe. En general es curso algo difícil, pero se logra. Es importante saber con anticipación qué se va a hacer ese día en clase. El profe es super buena gente y ayuda mucho.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '3a57ae311fc832b1b472399bb540cfb4fd8225d22eb62f642cf77106dfe3c2cc'::TEXT, ARRAY[3181, 3179]::BIGINT[]),
    (540::BIGINT, 'El es muy buena persona y tambien profe, se gana la confianza de los estudiantes y si no entiendes algo te lo explica. Es bastante desordenado con sus apuntes en la pizarra, asi que es aconsejable que leas mucho por aparte.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases largas', 'Brinda apoyo']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '874808b65d6222c11c1cf9b25b0355ff7bda97ba3e5bd2bd567b6ca91c6d59a0'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'Ayuda demasiado, es el mejor profe. Incluso ayuda con teoría si uno le pide ayuda. El curso es una gozada, se pasa super bien. Aprendí demasiado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'c3fca53858df4d259407c7db4b1b2307fca036a978bc7c3ad796370ce4359aab'::TEXT, ARRAY[3181, 3179]::BIGINT[]),
    (540::BIGINT, 'Para laboratorio califica muy duro, tanto informes como evaluaciones; pero es buena persona, si usted habla con él fijo le ayuda. Para lab no lo recomiendo'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo']::TEXT[], '2018-10-30T00:00:00+00:00'::TIMESTAMPTZ, '52b177ade95e4bf1f7e28838da26061316180a4116bf5d85efb82600e1ef8070'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '02f9098e94db42b690c7d1cab7b7bed7595bb2c10f6cb01484c756140e612d0b'::TEXT, ARRAY[613]::BIGINT[]),
    (540::BIGINT, 'Es un amor de persona. Explica lo suficientemente claro para un laboratorio. Ayuda bastante. Los informes se entregan la semana siguiente. Muy recomendado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '503828ba3685e2e91dd375e3a90a70ed48a8cc5eb40c7ba81bf09101599d050e'::TEXT, ARRAY[1433]::BIGINT[]),
    (540::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-22T00:00:00+00:00'::TIMESTAMPTZ, '11f5cdc785a237b31624856f8dfc024c9f31d33f829a17e4e961ae586b5fc6e2'::TEXT, ARRAY[567, 613, 1433, 2738, 3181, 3179]::BIGINT[]),
    (540::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '33b4e55bbb0253468f32c0bb151f7d8c1ff3355283720167c290a082d2d5f254'::TEXT, ARRAY[1434]::BIGINT[]),
    (540::BIGINT, 'De los mejores profes, con gran interés en el bienestar de sus estudiantes, es muy agradable y el curso es llevadero con él'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'c238a2bb516199cd1f249e2ee7664529cedcaf79daa8a7f11f92e9f687c7a40f'::TEXT, ARRAY[1433, 2738, 3179]::BIGINT[]),
    (540::BIGINT, 'El profe es muy pura vida, sin embargo califica super duro. No explica muchas cosas de teoría que luego salen en el examen por lo que se deben apoyar en el folleto y material complementario. Ayuda montones ir a consulta.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '03f408288a784148930e019d20e6bf3862129e5ab40749351e719e4b0fd10aea'::TEXT, ARRAY[2738, 3179, 3181]::BIGINT[]),
    (540::BIGINT, 'El profe es un amor de persona, los quices son en grupos y a libro abierto, esto es demasiado bueno porque ayuda mucho a la nota. A veces cuesta un poco entender la materia pero con la práctica se aprende. Si el profe nota que usted se ha esforzado es probable que lo ayude si necesita puntos al fina'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '7597e39be0099dd8feabfa1b584037dec4741a51a3dc661703f5b4c3277a72a1'::TEXT, ARRAY[1434]::BIGINT[]),
    (540::BIGINT, 'Es un muy profe, lo ayuda a uno muchísimo. Su clase se hace interesante aunque a veces se desvíe el tema.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'f8b999070c557db4515959d4aa8db47a6d2babf6931f0fc4a604d3ed5e1bd2ed'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'b624bb4ec2b2d4ce3c48ca2c9b88f07a5cfcba0ca712c8b039d8f472b1d5b635'::TEXT, ARRAY[2738, 3179, 3181]::BIGINT[]),
    (540::BIGINT, 'El profe es una teja como persona, siempre está dispuesto a ayudarle, a aclararle las dudas.Sus explicaciones no necesariamente son las mejores, ya que a veces se desvía del tema y uno se pierde. Hace muchos quices, rudillos, pero así uno se ve obligado a estudiar.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-19T00:00:00+00:00'::TIMESTAMPTZ, '1067fd8022c84e39d43a4d82af9d659df0d1a8018feda3d129d5a4538963e720'::TEXT, ARRAY[568]::BIGINT[]),
    (540::BIGINT, 'El profe José, es sin duda el mejor para laboratorio, la práctica la explica sencilla y siempre va guiando el procedimiento. Hace quices duros y califica rudo pero atiende a las consultas cuando sea.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '61663216d88b2b58169c379b8a678246b020d068861526792d0364589071f3aa'::TEXT, ARRAY[1433]::BIGINT[]),
    (540::BIGINT, 'El mejor profesor sin duda, ayuda bastante, califica suave y se interesa muchísimo en que usted aprenda y como persona es excelente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'da8001e2c7b29d4d8e0f178fadd56f82ed484c413fc91631a1ae8c0b56d1d0d9'::TEXT, ARRAY[613]::BIGINT[]),
    (540::BIGINT, 'El mejor profesor de la vida, en serio'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-25T00:00:00+00:00'::TIMESTAMPTZ, '069fe9d51524ec926d9f528309cac96c9a428868e97422f655658cf1a56caa58'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Este profesor es un personaje sacado de los bajos más profundos de los potreros. Su manera peculiar de hablar y dar la clase la hacen entretenida, aún así parece conocer de la materia, por lo que es una buena combinación.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'a77d3a3998fd3a1166b48dbd1f57990d3e67dcb509403c9aa68407bb96f5f554'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '5e5461f2c87d2ea7f67e33482d32b9f16529bed3ae032b5f5a5f9db4a6bd6eab'::TEXT, ARRAY[1433]::BIGINT[]),
    (540::BIGINT, 'Lo llevé con el en el 2015. Leí muy buenos comentarios sobre él, pero deben ser más críticos. No es el mejor profesor del mundo, no explica, califica tirando a duro. O sea si no explica mejor dicha califica duro, ya que es muy basto en las explicaciones. Hay que ser autodidacta.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '0f79740917db0b72d895c2fbece88ef3b465fe937778d7288702be5a740a1977'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'como persona excelente, como profe hace lo que puede por ayudarle al estudiante a salir adelante con el curso, se interesa por el aprendizaje de todos lo que también están interesados en el curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, '07dceb1defb56a4a420829709b584f9252a15a0720b3ff2f39aedb932f0fccaa'::TEXT, ARRAY[1434]::BIGINT[]),
    (540::BIGINT, 'Para Lab es excelente. Súper pura vida, da confianza para preguntarle cualquier cosa, la libreta la revisa al final del semestre, ayuda mucho con informes si va a consulta, etc. Califica medio rudillo, es lo único.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, '2e527c91d4e74d2a859a3d193a7d7408adc0978ae5160c72036ed08104ac65bb'::TEXT, ARRAY[1433]::BIGINT[]),
    (540::BIGINT, 'Explica masomenos , pero su interés con los estudiantes hace q la clase se vuelva buena , califica relativamente duro, pero es flexible .'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2016-05-04T00:00:00+00:00'::TIMESTAMPTZ, 'c945b32cb1bdaf6db702d80a339ae667a76ab5d8a1d17f856bba956a00af83d0'::TEXT, ARRAY[1433]::BIGINT[]),
    (540::BIGINT, 'El es un amor de persona, es súper buena gente, la clase se hace muy entretenida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-26T00:00:00+00:00'::TIMESTAMPTZ, '9cdc1ab79ed1553ddc6596275f20293bfa12e5bdaf679287a7865b1f9832f6fa'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Súper Recomendado!!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-26T00:00:00+00:00'::TIMESTAMPTZ, '7dd451d80ae35f1a95d7daa1df8a69835eac3d5ef5171c312c8a53c9f9db66d7'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, '¡Deseara que fuera mi abuelito! El es súper súper amable, bondadoso y bueno; como profesor y persona. Solo hay 2 cosas quizá negativas: 1) de tan bueno que es, algunos se vuelven demasiado vago 2) su metodología es tan fácil que recibir con otros profes de química más exigentes será difícil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-11T00:00:00+00:00'::TIMESTAMPTZ, '8b4a14545aaf2cc13efd4ae289357dc74ab95a9e65fcf6045a0ccc28833dcea8'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, '¡Excelente! :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-28T00:00:00+00:00'::TIMESTAMPTZ, 'b7c8dab23614c2ee03d150e60857294849f2bad0d4a00caf555baa81574979b1'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Es demasiado bueno como profesor y como persona. Explica de una forma muy clara, califica normal y en serio se aprende y las clases son muy entretenidas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'b8d6fe48d95161ee35647ae539111cb0a6aebe39021e28631c4a2106a3e481ae'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '7a0ff426faf640c8c460796d37ae7f11d40b211ea62c0f9ccc774954fc3e2ff3'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Un amor de persona!!! si no pasa algo con él difícilmente lo haga con otro profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-23T00:00:00+00:00'::TIMESTAMPTZ, '95c81272fbb867ba6f4ed593fa96a47c792fc93403d0eceae6b1d5da35faa4be'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, '¡EL profe!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-21T00:00:00+00:00'::TIMESTAMPTZ, '99151d01db0cead6de86879d378d2a13052484580e098ce78e22db50efaccad9'::TEXT, ARRAY[613]::BIGINT[]),
    (540::BIGINT, 'Es un buen profe. Ayuda demasiado en clase, cuando uno no entiende algo él se lo explica o te ayuda en la practica, super recomendado y es demasiado pura vida!!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-14T00:00:00+00:00'::TIMESTAMPTZ, '6f4f835a4e8c26a51345eacdd0099f394b49c834bf07b80a3e677a02c586662f'::TEXT, ARRAY[613]::BIGINT[]),
    (540::BIGINT, 'Excelente! Califica muy suave, ambiente de trabajo con demasiada confianza, explica antes de los quices (no es necesario estudiar), no jode mucho con la libreta y el trato hacia los estudiantes es genial!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '5716e359856ce643399c3f8e59d25ccbca08ba398f6a36d6e8796a5fe6e9da6f'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Es un poco desordenado para calificar, pero explica muy bien y es buena gente. El curso se vuelve muy llevadero'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'fafd800eee04d51c5f04fd98019567040323cb6a3805c1584513761414d890d2'::TEXT, ARRAY[1433]::BIGINT[]),
    (540::BIGINT, 'Mejor profesor que pueda haber :), ex´ñica muy claro y ayuda siempre que pueda, además del carisma que presenta con los estudiantes'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'fe19b8f07f88eb86ae9a24b5f066ce1f4ee1f6362919692b8a3ad3d89801eb2a'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Muy recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'fb306d29dd5557a0d543f34c892913b61fb1f67cbf67eedfe1c3cdb89cf7dbca'::TEXT, ARRAY[567, 613, 1433, 2738, 3181, 3179]::BIGINT[]),
    (540::BIGINT, 'Excelente profesor, comprensivo, paciente, califica suave, y exámenes cortos sencillos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'b3e83b68f11acc4d28357bcff21acee8d7facfc600fbd146f764af285d71d2c9'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Califica justo, los exámenes y quices tienen cierto grado de dificultad, pero el profe es super bueno enseñando y muy amable con los estudiantes.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '672219941be0ea4891739b3e9d909621a295ea71d971496afe04155bff90d77e'::TEXT, ARRAY[2738]::BIGINT[]),
    (540::BIGINT, 'Excelente profesor.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-26T00:00:00+00:00'::TIMESTAMPTZ, '10d25b5e315651838609ae734f4f7bf00bc321350861c9da8938d4e928597c88'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'c04f19ffc306b9bb6d3753937e17e32f405803bf311d9a4d92dd1fbf0dfddaee'::TEXT, ARRAY[613, 3179, 3181, 2738, 1433]::BIGINT[]),
    (540::BIGINT, 'Excelente profe, clases entretenidas y muchisima paciencia. Recomendado!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '7f5636a9eadc24f176d888fced55f8f15ee3eeeebc05fd69d93b6d3b02624ee8'::TEXT, ARRAY[1433]::BIGINT[]),
    (540::BIGINT, 'Excelente profesor y persona ! Lo recomiendo !'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '18792e66c18b395484bb89aa02eb5eb6fa01c0e4b610475ecdfe4e9c35bbfaad'::TEXT, ARRAY[567, 613, 1433, 2738, 3181, 3179]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
